style.css:
:root {
  bg-url: url("https://files.catbox.moe/gkyi1q.mp4");
}

html, body {
  height: 100%;
}

body {
  position: relative;
  background: transparent !important; 
}


body::before {
  content: "";
  position: fixed;
  inset: 0;
  background-image: var(--bg-url);
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  filter: blur(2px);
  z-index: -1;
  pointer-events: none;
  transform: translateZ(0); 
}
